40	            $data = $this->request($professional, 'POST', '/v2/catalog/search', [], $body);
41	            $objects = is_array($data['objects'] ?? null) ? $data['objects'] : [];
42	            $latestTime = is_string($data['latest_time'] ?? null) ? $data['latest_time'] : $latestTime;
43	            $cursor = is_string($data['cursor'] ?? null) ? $data['cursor'] : null;
44	
45	            foreach ($objects as $object) {
46	                if (! is_array($object)) {
47	                    continue;
48	                }
49	
50	                $type = (string) ($object['type'] ?? '');
51	                if ($type === 'CATEGORY') {
52	                    $categoryId = (string) ($object['id'] ?? '');
53	                    if ($categoryId === '') {
54	                        continue;
