81	
82	                $itemVersion = isset($object['version']) ? (int) $object['version'] : null;
83	                $itemDeleted = (bool) ($object['is_deleted'] ?? false);
84	
85	                if ($itemDeleted) {
86	                    $services[] = [
87	                        'item_id' => $itemId,
88	                        'item_version' => $itemVersion,
89	                        'deleted' => true,
90	                    ];
91	
92	                    continue;
93	                }
94	
95	                $itemData = is_array($object['item_data'] ?? null) ? $object['item_data'] : [];
