207	    /**
208	     * @param  array<string, string|int|float|bool|null>  $query
209	     * @param  array<string, mixed>|null  $body
210	     * @return array<string, mixed>
211	     */
212	    public function request(
213	        Professional $professional,
214	        string $method,
215	        string $path,
216	        array $query = [],
217	        ?array $body = null
218	    ): array {
219	        $token = $this->tokenService->getAccessToken($professional);
220	
221	        $response = $this->makeRequest($token, $method, $path, $query, $body);
222	
223	        // Access token might have been revoked/expired unexpectedly; refresh once.
224	        if ($response->status() === 401) {
225	            $token = $this->tokenService->refreshAccessToken($professional);
226	            $response = $this->makeRequest($token, $method, $path, $query, $body);
227	        }
228	
229	        $payload = $response->json();
230	        if (! is_array($payload)) {
231	            $payload = [];
232	        }
233	
234	        if (! $response->successful()) {
235	            $status = $response->status();
236	            $message = sprintf('Square API request failed: %s %s (HTTP %s)', $method, $path, $status);
237	            $errors = is_array($payload['errors'] ?? null) ? $payload['errors'] : null;
238	            if (is_array($errors) && isset($errors[0]) && is_array($errors[0])) {
239	                $first = $errors[0];
240	                $detail = isset($first['detail']) && is_string($first['detail']) ? trim($first['detail']) : '';
241	                $code = isset($first['code']) && is_string($first['code']) ? trim($first['code']) : '';
242	                $category = isset($first['category']) && is_string($first['category']) ? trim($first['category']) : '';
243	
244	                $parts = [];
245	                if ($code !== '') {
246	                    $parts[] = $code;
247	                }
248	                if ($category !== '') {
249	                    $parts[] = $category;
250	                }
251	                $meta = $parts ? sprintf(' [%s]', implode('/', $parts)) : '';
252	                $suffix = $detail !== '' ? sprintf(': %s', $detail) : '';
253	                $message = sprintf('Square API %s %s failed (HTTP %s)%s%s', strtoupper($method), $path, $status, $meta, $suffix);
254	            }
255	
256	            throw new SquareApiException($message, $status, $payload);
257	        }
258	
259	        return $payload;
260	    }
261	
262	    /**
263	     * @param  array<string, string|int|float|bool|null>  $query
264	     * @param  array<string, mixed>|null  $body
265	     */
266	    private function makeRequest(
267	        string $accessToken,
268	        string $method,
269	        string $path,
270	        array $query = [],
271	        ?array $body = null
272	    ): Response {
273	        $request = Http::acceptJson()
274	            ->asJson()
275	            ->timeout(30)
276	            ->withToken($accessToken)
277	            ->withHeaders([
278	                'Square-Version' => '2025-10-16',
279	            ]);
280	
281	        $url = $this->baseUrl().$path;
282	
283	        return match (strtoupper($method)) {
284	            'GET' => $request->get($url, $query),
285	            'DELETE' => $request->delete($url, $query),
286	            'POST' => $request->post($url.($query ? '?'.http_build_query($query) : ''), $body ?? []),
287	            'PUT' => $request->put($url.($query ? '?'.http_build_query($query) : ''), $body ?? []),
288	            'PATCH' => $request->patch($url.($query ? '?'.http_build_query($query) : ''), $body ?? []),
289	            default => throw new SquareApiException('Unsupported Square request method: '.$method),
290	        };
291	    }
292	
293	    private function baseUrl(): string
294	    {
295	        $environment = strtolower((string) config('services.square.environment', 'production'));
296	        if ($environment === 'sandbox') {
297	            return 'https://connect.squareupsandbox.com';
298	        }
299	
300	        return 'https://connect.squareup.com';
301	    }
302	}
