3	namespace App\Services\Shopify\Client;
4	
5	use App\Exceptions\Shopify\ShopifyGraphQLException;
6	use App\Exceptions\Shopify\ShopifyThrottledException;
7	use App\Exceptions\Shopify\ShopifyTransportException;
8	use Illuminate\Http\Client\ConnectionException;
9	use Illuminate\Http\Client\Response;
10	use Illuminate\Support\Facades\Http;
11	
12	/**
13	 * Single entry point for all Shopify Admin API calls.
14	 *
15	 * Handles:
16	 *   - GraphQL with throttle-aware in-process retries
17	 *   - REST with 429/Retry-After honouring
18	 *   - Bulk operation helpers with per-shop mutex
19	 *   - Typed exceptions that the queue's backoff() retry can handle
20	 *
21	 * Call sites pass shop_domain + access_token + api_version and get back
22	 * a standard Illuminate Http Response (or a throw). Throttle state is
23	 * tracked out-of-band via ShopifyBudgetTracker and reconciled from
24	 * extensions.cost.throttleStatus on every response.
25	 *
26	 * NOTE: budget pre-acquisition and THROTTLED retry are wired in the graphql()
27	 * method — see preAcquireBudget(), reconcileFromResponse(), and isThrottled().
28	 */
29	class ShopifyAdminClient
30	{
31	    public function __construct(
32	        private readonly ShopifyBudgetTracker $budget,
33	        private readonly ShopifyCostTracker $cost,
34	        private readonly ShopifyMetrics $metrics,
35	        private readonly ShopifyBulkOperationLock $bulkLock,
36	    ) {}
37	
38	    /**
39	     * Execute a GraphQL request against the Shopify Admin API.
40	     *
41	     * Pre-acquires from the local token bucket before sending and reconciles
42	     * bucket state from the authoritative throttleStatus in the response.
43	     *
44	     * @throws ShopifyGraphQLException top-level GraphQL errors (excluding THROTTLED)
45	     * @throws ShopifyTransportException non-2xx HTTP, timeout, or connection failure
46	     */
47	    public function graphql(
48	        string $shopDomain,
49	        string $accessToken,
50	        string $apiVersion,
51	        string $query,
52	        array $variables = [],
53	        ?int $timeoutSeconds = null,
54	    ): Response {
55	        $timeout = $timeoutSeconds ?? (int) config('services.shopify.throttle.default_timeout', 20);
56	        $maxRetries = (int) config('services.shopify.throttle.max_inprocess_retries', 3);
57	        $maxWait = (int) config('services.shopify.throttle.max_wait_ms', 5000);
58	        $queryHash = sha1($query);
59	        $attempt = 0;
60	
61	        while (true) {
62	            $this->preAcquireBudget($shopDomain, $queryHash);
63	            $started = microtime(true);
64	            $response = $this->post($shopDomain, $accessToken, $apiVersion, $query, $variables, $timeout);
65	            $this->reconcileFromResponse($response, $shopDomain, $queryHash, $started);
66	
67	            if ($this->isThrottled($response)) {
68	                $wait = $this->throttleWaitMs($response, $maxWait);
69	                if ($attempt >= $maxRetries) {
70	                    throw new ShopifyThrottledException($shopDomain, $wait, $attempt, $queryHash);
71	                }
72	                $this->metrics->throttled($shopDomain, $wait, $attempt + 1);
73	                // Blocks the worker thread — keep max_inprocess_retries low (default 3).
74	                usleep($wait * 1000);
75	                $attempt++;
76	
77	                continue;
78	            }
79	
80	            $this->handleGraphqlErrors($response, $shopDomain, $queryHash);
81	
82	            return $response;
83	        }
84	    }
85	
86	    /**
87	     * Execute a REST request against the Shopify Admin API.
88	     *
89	     * REST throttling is bucket-based (40 calls on standard, 80 on Plus) and
90	     * signalled via HTTP 429 + Retry-After. Low-volume in our codebase so we
91	     * only react to 429 rather than pre-throttling.
92	     *
93	     * @param  string  $method  'GET'|'POST'|'PUT'|'DELETE'
94	     * @param  string  $path  must start with `/admin/...`
95	     * @param  array<string, mixed>  $body
96	     * @param  bool  $allow401  pass true for token-revoke calls where 401 means "already revoked"
97	     *
98	     * @throws ShopifyTransportException on non-2xx (excluding 401 when $allow401 is true)
99	     */
100	    public function rest(
101	        string $method,
102	        string $shopDomain,
103	        string $accessToken,
104	        string $path,
105	        array $body = [],
106	        ?int $timeoutSeconds = null,
107	        bool $allow401 = false,
108	    ): Response {
109	        $timeout = $timeoutSeconds ?? (int) config('services.shopify.throttle.default_timeout', 20);
110	        $maxRetries = (int) config('services.shopify.throttle.max_inprocess_retries', 3);
111	        $url = "https://{$shopDomain}{$path}";
112	
113	        $attempt = 0;
114	        while (true) {
115	            try {
116	                $pending = Http::withHeaders(['X-Shopify-Access-Token' => $accessToken])->timeout($timeout);
117	                $response = match (strtoupper($method)) {
118	                    'GET' => $pending->get($url, $body),
119	                    'POST' => $pending->post($url, $body),
120	                    'PUT' => $pending->put($url, $body),
121	                    'DELETE' => $pending->delete($url, $body),
122	                    default => throw new \InvalidArgumentException("Unsupported HTTP method: {$method}"),
123	                };
124	            } catch (ConnectionException $e) {
125	                throw new ShopifyTransportException($shopDomain, 0, $e->getMessage(), $e);
126	            }
127	
128	            if ($response->status() === 429 && $attempt < $maxRetries) {
129	                $wait = max(1, (int) $response->header('Retry-After')) * 1000; // header absent → floor to 1 s
130	                $this->metrics->throttled($shopDomain, $wait, $attempt + 1);
131	                // Blocks the worker thread — keep max_inprocess_retries low (default 3).
132	                usleep($wait * 1000);
133	                $attempt++;
134	
135	                continue;
136	            }
137	
138	            if ($response->successful()) {
139	                return $response;
140	            }
141	
142	            if ($allow401 && $response->status() === 401) {
143	                return $response;
144	            }
145	
146	            throw new ShopifyTransportException($shopDomain, $response->status(), (string) $response->body());
147	        }
148	    }
149	
150	    /**
151	     * Start a `bulkOperationRunQuery`. Returns the operation GID.
152	     *
153	     * Acquires the per-shop bulk lock; only one bulk op may be in flight at a time.
154	     * Caller is responsible for calling `waitForBulkOperation()` which releases
155	     * the lock on terminal state.
156	     */
157	    public function bulkQuery(
158	        string $shopDomain,
159	        string $accessToken,
160	        string $apiVersion,
161	        string $query,
162	    ): string {
163	        if (! $this->bulkLock->acquire($shopDomain)) {
164	            $this->metrics->bulkLockContended($shopDomain);
165	            throw new \RuntimeException("Shopify bulk operation already in progress for {$shopDomain}");
166	        }
167	
168	        $mutation = <<<'GRAPHQL'
169	        mutation bulkOperationRunQuery($query: String!) {
170	          bulkOperationRunQuery(query: $query) {
171	            bulkOperation { id status }
172	            userErrors { field message }
173	          }
174	        }
175	        GRAPHQL;
176	
177	        try {
178	            $response = $this->graphql($shopDomain, $accessToken, $apiVersion, $mutation, ['query' => $query]);
179	        } catch (\Throwable $e) {
180	            $this->bulkLock->release($shopDomain);
181	            throw $e;
182	        }
183	
184	        $userErrors = $response->json('data.bulkOperationRunQuery.userErrors', []);
185	
186	        if (! empty($userErrors)) {
187	            $this->bulkLock->release($shopDomain);
188	            throw new \RuntimeException('Shopify bulkOperationRunQuery userErrors: '.json_encode($userErrors));
189	        }
190	
191	        return (string) $response->json('data.bulkOperationRunQuery.bulkOperation.id');
192	    }
193	
194	    /**
195	     * Start a `bulkOperationRunMutation`. Returns the operation GID.
196	     * Same locking semantics as bulkQuery.
197	     */
198	    public function bulkMutation(
199	        string $shopDomain,
200	        string $accessToken,
201	        string $apiVersion,
202	        string $mutation,
203	        string $stagedUploadPath,
204	    ): string {
205	        if (! $this->bulkLock->acquire($shopDomain)) {
206	            $this->metrics->bulkLockContended($shopDomain);
207	            throw new \RuntimeException("Shopify bulk operation already in progress for {$shopDomain}");
208	        }
209	
210	        $runner = <<<'GRAPHQL'
211	        mutation bulkOperationRunMutation($mutation: String!, $stagedUploadPath: String!) {
212	          bulkOperationRunMutation(mutation: $mutation, stagedUploadPath: $stagedUploadPath) {
213	            bulkOperation { id status }
214	            userErrors { field message }
215	          }
216	        }
217	        GRAPHQL;
218	
219	        try {
220	            $response = $this->graphql($shopDomain, $accessToken, $apiVersion, $runner, [
221	                'mutation' => $mutation,
222	                'stagedUploadPath' => $stagedUploadPath,
223	            ]);
224	        } catch (\Throwable $e) {
225	            $this->bulkLock->release($shopDomain);
226	            throw $e;
227	        }
228	
229	        $userErrors = $response->json('data.bulkOperationRunMutation.userErrors', []);
230	
231	        if (! empty($userErrors)) {
232	            $this->bulkLock->release($shopDomain);
233	            throw new \RuntimeException('Shopify bulkOperationRunMutation userErrors: '.json_encode($userErrors));
234	        }
235	
236	        return (string) $response->json('data.bulkOperationRunMutation.bulkOperation.id');
237	    }
238	
239	    /**
240	     * Poll a bulk operation until it reaches a terminal state.
241	     * Releases the per-shop bulk lock on terminal state.
242	     *
243	     * WARNING: synchronous — blocks the Horizon worker for up to $timeoutSeconds.
244	     * Run in a dedicated long-running job, not an inline service call.
245	     *
246	     * @return array{status: string, url: string|null, error_code: string|null}
247	     */
248	    public function waitForBulkOperation(
249	        string $shopDomain,
250	        string $accessToken,
251	        string $apiVersion,
252	        string $operationId,
253	        int $pollIntervalMs = 2000,
254	        int $timeoutSeconds = 600,
255	    ): array {
256	        $query = <<<'GRAPHQL'
257	        query bulkOperationStatus($id: ID!) {
258	          node(id: $id) { ... on BulkOperation { id status errorCode url } }
259	        }
260	        GRAPHQL;
261	
262	        $deadline = microtime(true) + $timeoutSeconds;
263	        $terminal = ['COMPLETED', 'FAILED', 'CANCELED', 'EXPIRED'];
264	
265	        while (microtime(true) < $deadline) {
266	            try {
267	                $response = $this->graphql($shopDomain, $accessToken, $apiVersion, $query, ['id' => $operationId]);
268	            } catch (\Throwable $e) {
269	                $this->bulkLock->release($shopDomain);
270	                throw $e;
271	            }
272	            $node = $response->json('data.node', []);
273	            $status = (string) ($node['status'] ?? 'UNKNOWN');
274	
275	            if (in_array($status, $terminal, true)) {
276	                $this->bulkLock->release($shopDomain);
277	
278	                return [
279	                    'status' => $status,
280	                    'url' => $node['url'] ?? null,
281	                    'error_code' => $node['errorCode'] ?? null,
282	                ];
283	            }
284	
285	            usleep($pollIntervalMs * 1000);
286	        }
287	
288	        // Timed out before terminal — release lock so shop isn't stuck
289	        $this->bulkLock->release($shopDomain);
290	        throw new \RuntimeException("Shopify bulk operation {$operationId} on {$shopDomain} timed out after {$timeoutSeconds}s");
291	    }
292	
293	    private function post(
294	        string $shopDomain,
295	        string $accessToken,
296	        string $apiVersion,
297	        string $query,
298	        array $variables,
299	        int $timeout,
300	    ): Response {
301	        try {
302	            $response = Http::withHeaders([
303	                'X-Shopify-Access-Token' => $accessToken,
304	                'Content-Type' => 'application/json',
305	            ])
306	                ->timeout($timeout)
307	                ->post("https://{$shopDomain}/admin/api/{$apiVersion}/graphql.json", array_filter([
308	                    'query' => $query,
309	                    'variables' => ! empty($variables) ? $variables : null,
310	                ]));
311	        } catch (ConnectionException $e) {
312	            throw new ShopifyTransportException($shopDomain, 0, $e->getMessage(), $e);
313	        }
314	
315	        if (! $response->successful()) {
316	            throw new ShopifyTransportException($shopDomain, $response->status(), (string) $response->body());
317	        }
318	
319	        return $response;
320	    }
321	
322	    private function handleGraphqlErrors(Response $response, string $shopDomain, string $queryHash): void
323	    {
324	        $errors = $response->json('errors', []);
325	        if (empty($errors)) {
326	            return;
327	        }
328	
329	        $this->metrics->graphqlError($shopDomain, $queryHash, $errors);
330	        throw new ShopifyGraphQLException($shopDomain, $errors, $queryHash);
331	    }
332	
333	    private function isThrottled(Response $response): bool
334	    {
335	        $errors = $response->json('errors', []);
336	        foreach ($errors as $error) {
337	            if (($error['extensions']['code'] ?? '') === 'THROTTLED') {
338	                return true;
339	            }
340	        }
341	
342	        return false;
343	    }
344	
345	    /**
346	     * Returns how long to wait before retrying a THROTTLED response, in milliseconds.
347	     * Falls back to 1 000 ms (capped at max_wait_ms) when no throttleStatus is available.
348	     */
349	    private function throttleWaitMs(Response $response, int $maxWait): int
350	    {
351	        $available = $response->json('extensions.cost.throttleStatus.currentlyAvailable');
352	        $restoreRate = $response->json('extensions.cost.throttleStatus.restoreRate');
353	
354	        if ($restoreRate > 0 && $available !== null) {
355	            // Estimate how many ms until 10 points are available (minimum useful budget)
356	            $needed = max(0, 10 - (int) $available);
357	            $waitMs = (int) ceil(($needed / $restoreRate) * 1000);
358	
359	            return min($waitMs, $maxWait);
360	        }
361	
362	        return min(1000, $maxWait);
363	    }
364	
365	    /**
366	     * Reserve estimated cost from the local token bucket before sending the request.
367	     * If the bucket is insufficient, waits up to max_wait_ms then retries once;
368	     * any remaining deficit is accepted and left to the THROTTLED retry path.
369	     */
370	    private function preAcquireBudget(string $shopDomain, string $queryHash): void
371	    {
372	        $defaultRequested = (int) config('services.shopify.throttle.default_estimated_cost', 10);
373	        $estimated = $this->cost->estimate($queryHash, $defaultRequested);
374	        $max = (int) config('services.shopify.throttle.default_max_capacity', 1000);
375	        $rate = (int) config('services.shopify.throttle.default_restore_rate', 100);
376	        $maxWait = (int) config('services.shopify.throttle.max_wait_ms', 5000);
377	
378	        $result = $this->budget->tryAcquire($shopDomain, $estimated, $max, $rate);
379	
380	        if (! $result['acquired']) {
381	            $wait = min($result['wait_ms'], $maxWait);
382	            $this->metrics->budgetWait($shopDomain, $wait, $estimated);
383	            usleep($wait * 1000);
384	
385	            // Retry once after the wait — if still short, proceed anyway and
386	            // let the THROTTLED retry path handle it.
387	            // Result is intentionally discarded; we proceed regardless of outcome.
388	            $this->budget->tryAcquire($shopDomain, $estimated, $max, $rate);
389	        }
390	    }
391	
392	    /**
393	     * Overwrite local bucket state with Shopify's authoritative throttleStatus
394	     * and record the actual/requested cost ratio for future estimates.
395	     */
396	    private function reconcileFromResponse(Response $response, string $shopDomain, string $queryHash, float $started): void
397	    {
398	        $cost = $response->json('extensions.cost');
399	        if (! is_array($cost)) {
400	            return;
401	        }
402	
403	        $status = $cost['throttleStatus'] ?? [];
404	        if (isset($status['currentlyAvailable'])) {
405	            $this->budget->reconcile(
406	                $shopDomain,
407	                (int) $status['currentlyAvailable'],
408	            );
409	        }
410	
411	        $requested = (int) ($cost['requestedQueryCost'] ?? 0);
412	        $actual = (int) ($cost['actualQueryCost'] ?? 0);
413	        if ($requested > 0 && $actual > 0) {
414	            $this->cost->record($queryHash, $requested, $actual);
415	        }
416	
417	        $this->metrics->request(
418	            $shopDomain,
419	            $queryHash,
420	            (microtime(true) - $started) * 1000,
421	            $actual,
422	            (int) ($status['currentlyAvailable'] ?? 0), // 0 when throttleStatus absent — not a true empty-bucket signal
423	        );
424	    }
425	}
