17	    /**
18	     * @return array{services: array<int, array<string, mixed>>, latest_time: string|null}
19	     */
20	    public function fetchAppointmentServiceVariations(Professional $professional, ?string $beginTime = null): array
21	    {
22	        $services = [];
23	        $categoryNamesById = [];
24	        $latestTime = null;
25	        $cursor = null;
26	
27	        do {
28	            $body = [
29	                'object_types' => ['ITEM', 'CATEGORY'],
30	                'include_deleted_objects' => true,
31	            ];
32	
33	            if ($beginTime) {
34	                $body['begin_time'] = $beginTime;
35	            }
36	            if ($cursor) {
37	                $body['cursor'] = $cursor;
38	            }
39	
40	            $data = $this->request($professional, 'POST', '/v2/catalog/search', [], $body);
41	            $objects = is_array($data['objects'] ?? null) ? $data['objects'] : [];
42	            $latestTime = is_string($data['latest_time'] ?? null) ? $data['latest_time'] : $latestTime;
43	            $cursor = is_string($data['cursor'] ?? null) ? $data['cursor'] : null;
44	
45	            foreach ($objects as $object) {
46	                if (! is_array($object)) {
47	                    continue;
48	                }
49	
50	                $type = (string) ($object['type'] ?? '');
51	                if ($type === 'CATEGORY') {
52	                    $categoryId = (string) ($object['id'] ?? '');
53	                    if ($categoryId === '') {
54	                        continue;
55	                    }
56	
57	                    $categoryDeleted = (bool) ($object['is_deleted'] ?? false);
58	                    if ($categoryDeleted) {
59	                        unset($categoryNamesById[$categoryId]);
60	
61	                        continue;
62	                    }
63	
64	                    $categoryData = is_array($object['category_data'] ?? null) ? $object['category_data'] : [];
65	                    $categoryName = trim((string) ($categoryData['name'] ?? ''));
66	                    if ($categoryName !== '') {
67	                        $categoryNamesById[$categoryId] = $categoryName;
68	                    }
69	
70	                    continue;
71	                }
72	
73	                if ($type !== 'ITEM') {
74	                    continue;
75	                }
76	
77	                $itemId = (string) ($object['id'] ?? '');
78	                if ($itemId === '') {
79	                    continue;
80	                }
81	
82	                $itemVersion = isset($object['version']) ? (int) $object['version'] : null;
83	                $itemDeleted = (bool) ($object['is_deleted'] ?? false);
84	
85	                if ($itemDeleted) {
86	                    $services[] = [
87	                        'item_id' => $itemId,
88	                        'item_version' => $itemVersion,
89	                        'deleted' => true,
90	                    ];
91	
92	                    continue;
93	                }
94	
95	                $itemData = is_array($object['item_data'] ?? null) ? $object['item_data'] : [];
96	                $productType = strtoupper((string) ($itemData['product_type'] ?? ''));
97	                if ($productType !== 'APPOINTMENTS_SERVICE') {
98	                    continue;
99	                }
100	
101	                $categoryId = trim((string) ($itemData['category_id'] ?? ''));
102	                if ($categoryId === '') {
103	                    $categories = is_array($itemData['categories'] ?? null) ? $itemData['categories'] : [];
104	                    $firstCategory = $categories[0] ?? null;
105	                    if (is_array($firstCategory)) {
106	                        $categoryId = trim((string) ($firstCategory['id'] ?? ''));
107	                    }
108	                }
109	                if ($categoryId === '') {
110	                    $reportingCategory = is_array($itemData['reporting_category'] ?? null) ? $itemData['reporting_category'] : null;
111	                    if (is_array($reportingCategory)) {
112	                        $categoryId = trim((string) ($reportingCategory['id'] ?? ''));
113	                    }
114	                }
115	
116	                $variations = is_array($itemData['variations'] ?? null) ? $itemData['variations'] : [];
117	                foreach ($variations as $variation) {
118	                    if (! is_array($variation)) {
119	                        continue;
120	                    }
121	
122	                    $variationId = trim((string) ($variation['id'] ?? ''));
123	                    if ($variationId === '') {
124	                        continue;
125	                    }
126	
127	                    $variationDeleted = (bool) ($variation['is_deleted'] ?? false);
128	                    if ($variationDeleted) {
129	                        $services[] = [
130	                            'item_id' => $itemId,
131	                            'variation_id' => $variationId,
132	                            'item_version' => $itemVersion,
133	                            'deleted' => true,
134	                        ];
135	
136	                        continue;
137	                    }
138	
139	                    $variationData = is_array($variation['item_variation_data'] ?? null) ? $variation['item_variation_data'] : [];
140	                    $durationMs = isset($variationData['service_duration']) ? (int) $variationData['service_duration'] : null;
141	                    $price = is_array($variationData['price_money'] ?? null) ? $variationData['price_money'] : [];
142	
143	                    $services[] = [
144	                        'item_id' => $itemId,
145	                        'item_name' => (string) ($itemData['name'] ?? 'Service'),
146	                        'item_description' => isset($itemData['description']) ? (string) $itemData['description'] : null,
147	                        'item_version' => $itemVersion,
148	                        'variation_id' => $variationId,
149	                        'variation_name' => (string) ($variationData['name'] ?? ''),
150	                        'duration_minutes' => $durationMs !== null ? (int) round($durationMs / 60000) : null,
151	                        'price_cents' => isset($price['amount']) ? (int) $price['amount'] : null,
152	                        'currency_code' => isset($price['currency']) ? (string) $price['currency'] : null,
153	                        'available_for_booking' => (bool) ($variationData['available_for_booking'] ?? false),
154	                        'square_category_id' => $categoryId !== '' ? $categoryId : null,
155	                        'deleted' => false,
156	                    ];
157	                }
158	            }
159	        } while ($cursor !== null);
160	
161	        foreach ($services as &$service) {
162	            if (! is_array($service) || (bool) ($service['deleted'] ?? false)) {
163	                continue;
164	            }
165	            $rowCategoryId = trim((string) ($service['square_category_id'] ?? ''));
166	            $service['square_category_name'] = $rowCategoryId !== ''
167	                ? ($categoryNamesById[$rowCategoryId] ?? null)
168	                : null;
169	        }
