176	
177	    /**
178	     * Generic request method mirroring SquareApiClient::request().
179	     *
180	     * @param  array<string, string|int|float|bool|null>  $query
181	     * @param  array<string, mixed>|null  $body
182	     * @return array<string, mixed>
183	     */
184	    public function request(
185	        Professional $professional,
186	        string $method,
187	        string $path,
188	        array $query = [],
189	        ?array $body = null
190	    ): array {
191	        $token = $this->tokenService->getAccessToken($professional);
192	
193	        $response = $this->makeRequest($token, $method, $path, $query, $body);
194	
195	        // Access token might have been revoked/expired unexpectedly; refresh once.
196	        if ($response->status() === 401) {
197	            $token = $this->tokenService->refreshAccessToken($professional);
198	            $response = $this->makeRequest($token, $method, $path, $query, $body);
199	        }
200	
201	        $payload = $response->json();
202	        if (! is_array($payload)) {
203	            $payload = [];
204	        }
205	
206	        if (! $response->successful()) {
207	            $status = $response->status();
208	            $message = sprintf('Fresha API request failed: %s %s (HTTP %s)', $method, $path, $status);
209	            $errors = is_array($payload['errors'] ?? null) ? $payload['errors'] : null;
210	            if (is_array($errors) && isset($errors[0]) && is_array($errors[0])) {
211	                $first = $errors[0];
212	                $detail = isset($first['detail']) && is_string($first['detail']) ? trim($first['detail']) : '';
213	                $code = isset($first['code']) && is_string($first['code']) ? trim($first['code']) : '';
214	
215	                $parts = [];
216	                if ($code !== '') {
217	                    $parts[] = $code;
218	                }
219	                $meta = $parts ? sprintf(' [%s]', implode('/', $parts)) : '';
220	                $suffix = $detail !== '' ? sprintf(': %s', $detail) : '';
221	                $message = sprintf('Fresha API %s %s failed (HTTP %s)%s%s', strtoupper($method), $path, $status, $meta, $suffix);
222	            }
223	
224	            throw new FreshaApiException($message, $status, $payload);
225	        }
226	
227	        return $payload;
228	    }
229	
230	    /**
231	     * @param  array<string, string|int|float|bool|null>  $query
232	     * @param  array<string, mixed>|null  $body
233	     */
234	    private function makeRequest(
235	        string $accessToken,
236	        string $method,
237	        string $path,
238	        array $query = [],
239	        ?array $body = null
240	    ): Response {
241	        $request = Http::acceptJson()
242	            ->asJson()
243	            ->timeout(30)
244	            ->withToken($accessToken);
245	
246	        $url = $this->baseUrl().$path;
247	
248	        return match (strtoupper($method)) {
249	            'GET' => $request->get($url, $query),
250	            'DELETE' => $request->delete($url, $query),
251	            'POST' => $request->post($url.($query ? '?'.http_build_query($query) : ''), $body ?? []),
252	            'PUT' => $request->put($url.($query ? '?'.http_build_query($query) : ''), $body ?? []),
253	            'PATCH' => $request->patch($url.($query ? '?'.http_build_query($query) : ''), $body ?? []),
254	            default => throw new FreshaApiException('Unsupported Fresha request method: '.$method),
255	        };
256	    }
257	
258	    private function baseUrl(): string
259	    {
260	        $environment = strtolower((string) config('services.fresha.environment', 'production'));
261	        if ($environment === 'sandbox') {
262	            return 'https://partner-api-sandbox.fresha.com';
263	        }
264	
265	        return 'https://partner-api.fresha.com';
266	    }
267	}
